--
-- Table structure for table `project_info_node`
--

DROP TABLE IF EXISTS `project_info_node`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project_info_node` (
  `id` varchar(64) NOT NULL COMMENT '节点永久身份(UUID)，改名/挪位不换',
  `project_id` varchar(64) DEFAULT NULL COMMENT 'NULL=全局模板节点；非 NULL=该项目专属的增补节点',
  `parent_id` varchar(64) DEFAULT NULL COMMENT '父节点ID, NULL=根节点',
  `node_key` varchar(191) NOT NULL COMMENT '程序用稳定标识(如 base.customer_info)，建立后不可改',
  `node_name` varchar(255) NOT NULL COMMENT '节点显示名',
  `node_type` varchar(16) NOT NULL DEFAULT 'field' COMMENT '节点类型: root/group/field',
  `value_type` varchar(32) NOT NULL DEFAULT 'text' COMMENT '值类型: text/number/boolean/date/select/multi_select/person/attachment/json',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '同级排序(升序，建议留 10/20/30 间隔便于插入)',
  `required` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否必填（前端信息完整性提示用）',
  `allow_custom` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否允许在其下增补项目自定义子节点',
  `config` json DEFAULT NULL COMMENT '节点配置: 下拉选项、单位、占位提示等',
  `status` varchar(16) NOT NULL DEFAULT 'active' COMMENT '状态: active/disabled（停用保留历史与值，仅隐去）',
  `created_by` varchar(64) DEFAULT NULL COMMENT '创建人登录名（全局节点为管理员）',
  `created_at` varchar(30) NOT NULL COMMENT '创建时间',
  `updated_by` varchar(64) DEFAULT NULL COMMENT '最近修改人登录名',
  `updated_at` varchar(30) NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pin_project_key` (`project_id`,`node_key`),
  KEY `idx_pin_scope` (`project_id`,`status`),
  KEY `idx_pin_parent_sort` (`project_id`,`parent_id`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

