DROP TABLE IF EXISTS `project_info_value`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project_info_value` (
  `id` varchar(64) NOT NULL COMMENT '记录UUID',
  `project_id` varchar(64) NOT NULL COMMENT '值所属项目ID',
  `node_id` varchar(64) NOT NULL COMMENT '对应的节点ID（全局节点或本项目增补节点）',
  `value_json` json DEFAULT NULL COMMENT '节点值(原生JSON: 字符串/数字/数组/对象)',
  `created_at` varchar(30) NOT NULL COMMENT '创建时间',
  `updated_at` varchar(30) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) DEFAULT NULL COMMENT '最近修改人登录名',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_piv_project_node` (`project_id`,`node_id`),
  KEY `idx_piv_node` (`node_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

