--
-- Table structure for table `project_info_value_history`
--

DROP TABLE IF EXISTS `project_info_value_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project_info_value_history` (
  `id` varchar(64) NOT NULL COMMENT '记录UUID（时间有序，可当水位比较）',
  `project_id` varchar(64) NOT NULL COMMENT '所属项目ID（历史按项目隔离，必填）',
  `node_id` varchar(64) DEFAULT NULL COMMENT '被操作的节点ID；整树级操作为 NULL',
  `parent_id` varchar(64) DEFAULT NULL COMMENT '上级节点ID（删除记录据此在父节点历史里展示）',
  `node_key` varchar(191) NOT NULL DEFAULT '' COMMENT '写入时的节点标识快照',
  `node_name` varchar(255) NOT NULL DEFAULT '' COMMENT '写入时的节点名称快照',
  `node_type` varchar(16) DEFAULT NULL COMMENT '写入时的节点类型快照',
  `old_value` json DEFAULT NULL COMMENT '变更前的值（原生JSON）',
  `new_value` json DEFAULT NULL COMMENT '变更后的值（原生JSON）',
  `operation_type` varchar(16) NOT NULL COMMENT '操作类型: create/update/delete/node_create/node_move/node_rename',
  `changed_by` varchar(64) DEFAULT NULL COMMENT '操作人登录名（识别不到时为 NULL）',
  `changed_by_name` varchar(64) DEFAULT NULL COMMENT '操作人显示名',
  `change_reason` text COMMENT '变更原因（预留，当前多数为空）',
  `detail` text COMMENT '具体变动的人话描述（服务端拼好，前端直接展示）',
  `changed_at` varchar(30) NOT NULL COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_pivh_project_time` (`project_id`,`changed_at`),
  KEY `idx_pivh_project_node_time` (`project_id`,`node_id`,`changed_at`),
  KEY `idx_pivh_parent` (`project_id`,`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

